mapper.update:
UPDATE `inspection`.`inspection_process_sub` a
SET a.`INSPECTION_PROCESS_SUB_SIGN` = '0',
a.FINISH_TIME                   = #{params.FINISH_TIME}
WHERE
a.INSPECTION_PROCESS_SUB_ID LIKE '___03%'
AND a.`INSPECTION_TASK_ID` = #{params.TASK_ID}

UPDATE `inspection`.`inspection_process` a
SET
    a.`INSPECTION_PROCESS_SIGN` = '0',
    a.`IS_ACTIVE` = '1',
    a.FINISH_TIME               = #{params.FINISH_TIME}
WHERE
    a.INSPECTION_PROCESS_ID = #{params.PROC_ID}
    AND a.`INSPECTION_TASK_ID` = #{params.TASK_ID}
    AND a.INSPECTION_PROCESS_SIGN = '1'

UPDATE `inspection`.`inspection_process_sub` a
SET a.`INSPECTION_PROCESS_SUB_SIGN` = '0',
    a.FINISH_TIME                   = #{params.FINISH_TIME}
WHERE
    a.INSPECTION_PROCESS_SUB_ID = #{params.PROC_SUB_ID}
    AND a.`INSPECTION_TASK_ID` = #{params.TASK_ID}

UPDATE `inspection`.`inspection_process_sub_postsv` a
SET a.`INSPECTION_PROCESS_SUB_SIGN` = '0',
a.FINISH_TIME                   = #{params.FINISH_TIME}
WHERE
a.INSPECTION_PROCESS_SUB_ID = #{params.PROC_SUB_ID}
AND a.INSPECTION_PROCESS_SUB_SIGN = '1'
AND a.`INSPECTION_TASK_ID` = #{params.TASK_ID}

UPDATE `inspection`.`inspection_process_sub` a
SET a.`IS_ACTIVE` = '0'
WHERE
a.`INSPECTION_TASK_ID` = #{params.TASK_ID}
AND a.INSPECTION_PROCESS_SUB_ID = #{params.PROC_SUB_ID}
